			ce274SelectedInvocation(t, i, f.Target).Inputs[0].Path = "missing.bin"
		}},
		{"stale invocation input", func(i *project.ComponentInventory) {
			ce274SelectedInvocation(t, i, f.Target).Inputs[0].SHA256 = ce274ChangedHash()
